export default function PrivacyPolicy () {
  return (
    <div className="max-w-4xl mx-auto p-6">
      <h1 className="text-3xl font-bold mb-4">Kibzar Privacy Policy</h1>
      <p className="text-sm text-gray-500 mb-6">Last Updated: July 4, 2025</p>

      <p className="mb-4">Welcome to Kibzar (referred to as “we”, “us”, or “our”), a marketplace app that provides a platform for users to post, browse, and interact regarding items for sale...</p>
      {/* Keep going with the full policy in paragraphs. You can wrap each section in <h2> and <p> tags for clarity */}
    </div>
  );
};
